import React, { useState, useEffect } from 'react';

const API_URL = 'http://localhost:8000';

function App() {
  // Estados para empleados
  const [empleados, setEmpleados] = useState([]);
  const [nuevoEmpleado, setNuevoEmpleado] = useState({ nombre: '', area: '', puesto: '', salario_mensual: 0, fecha_ingreso: '' });

  // Estados para periodos
  const [periodos, setPeriodos] = useState([]);
  const [nuevoPeriodo, setNuevoPeriodo] = useState({ mes: 1, año: 2026, fecha_corte: '', total_general: 0 });

  // Estados para planillas
  const [planillas, setPlanillas] = useState([]);
  const [nuevaPlanilla, setNuevaPlanilla] = useState({
    periodo_id: 1,
    empleado_id: 1,
    sueldo_base: 0,
    horas_extras_diurnas: 0,
    horas_extras_nocturnas: 0,
    viaticos: 0,
    bono_extra: 0,
    aplica_nocturnidad: false,
    quincena25_aplica: false,
    monto_isss: 0,
    monto_afp: 0,
    monto_isr: 0,
    monto_neto: 0
  });

  // Cargar datos al inicio
  useEffect(() => {
    fetch(`${API_URL}/empleado`).then(res => res.json()).then(data => setEmpleados(data));
    fetch(`${API_URL}/periodo`).then(res => res.json()).then(data => setPeriodos(data));
    fetch(`${API_URL}/planilla`).then(res => res.json()).then(data => setPlanillas(data));
  }, []);

  // Crear empleado
  const crearEmpleado = async (e) => {
    e.preventDefault();
    const res = await fetch(`${API_URL}/empleado/`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(nuevoEmpleado)
    });
    const data = await res.json();
    setEmpleados([...empleados, data]);
    setNuevoEmpleado({ nombre: '', area: '', puesto: '', salario_mensual: 0, fecha_ingreso: '' });
  };

  // Crear periodo
  const crearPeriodo = async (e) => {
    e.preventDefault();
    const res = await fetch(`${API_URL}/periodo/`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(nuevoPeriodo)
    });
    const data = await res.json();
    setPeriodos([...periodos, data]);
    setNuevoPeriodo({ mes: 1, año: 2026, fecha_corte: '', total_general: 0 });
  };

  // Crear planilla
  const crearPlanilla = async (e) => {
    e.preventDefault();
    const res = await fetch(`${API_URL}/planilla/`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(nuevaPlanilla)
    });
    const data = await res.json();
    setPlanillas([...planillas, data]);
    setNuevaPlanilla({
      periodo_id: 1,
      empleado_id: 1,
      sueldo_base: 0,
      horas_extras_diurnas: 0,
      horas_extras_nocturnas: 0,
      viaticos: 0,
      bono_extra: 0,
      aplica_nocturnidad: false,
      quincena25_aplica: false,
      monto_isss: 0,
      monto_afp: 0,
      monto_isr: 0,
      monto_neto: 0
    });
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h1>🏢 Control de Planillas - Gasolinera Texaco</h1>
      <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
        {/* Sección Empleados */}
        <div style={{ border: '1px solid #ccc', padding: '15px', borderRadius: '8px', flex: 1 }}>
          <h2>👥 Empleados</h2>
          <form onSubmit={crearEmpleado}>
            <input placeholder="Nombre" value={nuevoEmpleado.nombre} onChange={e => setNuevoEmpleado({...nuevoEmpleado, nombre: e.target.value})} required />
            <input placeholder="Área" value={nuevoEmpleado.area} onChange={e => setNuevoEmpleado({...nuevoEmpleado, area: e.target.value})} required />
            <input placeholder="Puesto" value={nuevoEmpleado.puesto} onChange={e => setNuevoEmpleado({...nuevoEmpleado, puesto: e.target.value})} required />
            <input placeholder="Salario mensual" type="number" step="0.01" value={nuevoEmpleado.salario_mensual} onChange={e => setNuevoEmpleado({...nuevoEmpleado, salario_mensual: parseFloat(e.target.value)})} required />
            <input placeholder="Fecha ingreso (YYYY-MM-DD)" value={nuevoEmpleado.fecha_ingreso} onChange={e => setNuevoEmpleado({...nuevoEmpleado, fecha_ingreso: e.target.value})} required />
            <button type="submit">Agregar Empleado</button>
          </form>
          <ul>
            {empleados.map(emp => (
              <li key={emp.id}><b>{emp.nombre}</b> - {emp.puesto} (${emp.salario_mensual}) Ingreso: {emp.fecha_ingreso}</li>
            ))}
          </ul>
        </div>

        {/* Sección Períodos */}
        <div style={{ border: '1px solid #ccc', padding: '15px', borderRadius: '8px', flex: 1 }}>
          <h2>📅 Períodos</h2>
          <form onSubmit={crearPeriodo}>
            <input placeholder="Mes (1-12)" type="number" value={nuevoPeriodo.mes} onChange={e => setNuevoPeriodo({...nuevoPeriodo, mes: parseInt(e.target.value)})} required />
            <input placeholder="Año" type="number" value={nuevoPeriodo.año} onChange={e => setNuevoPeriodo({...nuevoPeriodo, año: parseInt(e.target.value)})} required />
            <input placeholder="Fecha corte (YYYY-MM-DD)" value={nuevoPeriodo.fecha_corte} onChange={e => setNuevoPeriodo({...nuevoPeriodo, fecha_corte: e.target.value})} required />
            <button type="submit">Agregar Período</button>
          </form>
          <ul>
            {periodos.map(per => (
              <li key={per.id}>Mes {per.mes}/{per.año} - Corte: {per.fecha_corte}</li>
            ))}
          </ul>
        </div>

        {/* Sección Planillas */}
        <div style={{ border: '1px solid #ccc', padding: '15px', borderRadius: '8px', flex: 1 }}>
          <h2>📄 Planillas</h2>
          <form onSubmit={crearPlanilla}>
            <select value={nuevaPlanilla.periodo_id} onChange={e => setNuevaPlanilla({...nuevaPlanilla, periodo_id: parseInt(e.target.value)})}>
              {periodos.map(per => <option key={per.id} value={per.id}>Período {per.mes}/{per.año}</option>)}
            </select>
            <select value={nuevaPlanilla.empleado_id} onChange={e => setNuevaPlanilla({...nuevaPlanilla, empleado_id: parseInt(e.target.value)})}>
              {empleados.map(emp => <option key={emp.id} value={emp.id}>{emp.nombre}</option>)}
            </select>
            <input placeholder="Sueldo base" type="number" step="0.01" value={nuevaPlanilla.sueldo_base} onChange={e => setNuevaPlanilla({...nuevaPlanilla, sueldo_base: parseFloat(e.target.value)})} required />
            <input placeholder="Horas extra diurnas" type="number" step="0.5" value={nuevaPlanilla.horas_extras_diurnas} onChange={e => setNuevaPlanilla({...nuevaPlanilla, horas_extras_diurnas: parseFloat(e.target.value)})} />
            <input placeholder="Horas extra nocturnas" type="number" step="0.5" value={nuevaPlanilla.horas_extras_nocturnas} onChange={e => setNuevaPlanilla({...nuevaPlanilla, horas_extras_nocturnas: parseFloat(e.target.value)})} />
            <input placeholder="Viáticos" type="number" step="0.01" value={nuevaPlanilla.viaticos} onChange={e => setNuevaPlanilla({...nuevaPlanilla, viaticos: parseFloat(e.target.value)})} />
            <input placeholder="Bono extra" type="number" step="0.01" value={nuevaPlanilla.bono_extra} onChange={e => setNuevaPlanilla({...nuevaPlanilla, bono_extra: parseFloat(e.target.value)})} />
            <label><input type="checkbox" checked={nuevaPlanilla.aplica_nocturnidad} onChange={e => setNuevaPlanilla({...nuevaPlanilla, aplica_nocturnidad: e.target.checked})} /> Aplica nocturnidad</label>
            <label><input type="checkbox" checked={nuevaPlanilla.quincena25_aplica} onChange={e => setNuevaPlanilla({...nuevaPlanilla, quincena25_aplica: e.target.checked})} /> Quincena 25</label>
            <input placeholder="Monto ISSS" type="number" step="0.01" value={nuevaPlanilla.monto_isss} onChange={e => setNuevaPlanilla({...nuevaPlanilla, monto_isss: parseFloat(e.target.value)})} />
            <input placeholder="Monto AFP" type="number" step="0.01" value={nuevaPlanilla.monto_afp} onChange={e => setNuevaPlanilla({...nuevaPlanilla, monto_afp: parseFloat(e.target.value)})} />
            <input placeholder="Monto ISR" type="number" step="0.01" value={nuevaPlanilla.monto_isr} onChange={e => setNuevaPlanilla({...nuevaPlanilla, monto_isr: parseFloat(e.target.value)})} />
            <input placeholder="Monto neto" type="number" step="0.01" value={nuevaPlanilla.monto_neto} onChange={e => setNuevaPlanilla({...nuevaPlanilla, monto_neto: parseFloat(e.target.value)})} />
            <button type="submit">Registrar Planilla</button>
          </form>
          <table border="1" style={{ width: '100%', marginTop: '10px' }}>
            <thead><tr><th>ID</th><th>Empleado</th><th>Período</th><th>Sueldo</th><th>Neto</th></tr></thead>
            <tbody>
              {planillas.map(pl => {
                const emp = empleados.find(e => e.id === pl.empleado_id);
                const per = periodos.find(p => p.id === pl.periodo_id);
                return (
                  <tr key={pl.id}>
                    <td>{pl.id}</td>
                    <td>{emp ? emp.nombre : '?'}</td>
                    <td>{per ? `${per.mes}/${per.año}` : '?'}</td>
                    <td>${pl.sueldo_base}</td>
                    <td>${pl.monto_neto}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

export default App;
